// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue } from '@skyramp/skyramp';
import { generateHash, verifyHash } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8055");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const generatePostResponse = await generateHash(client, URL_localhost, headers, "Directus");

    expect(getValue(generatePostResponse, "data"), 'generated hash encoding').toMatch(/^\$argon2(id|i|d)\$v=\d+\$m=\d+,t=\d+,p=\d+\$[A-Za-z0-9+/]+\$[A-Za-z0-9+/]+$/);
    expect(getValue(generatePostResponse, "errors"), 'no errors on generate').toBeNull();

    const generatedHash = getValue(generatePostResponse, "data") as string;

    const verifyPostResponse = await verifyHash(client, URL_localhost, headers, "Directus", generatedHash);

    expect(getValue(verifyPostResponse, "data"), 'verify matching string').toBe(true);
    expect(getValue(verifyPostResponse, "errors"), 'no errors on verify').toBeNull();
});
